#define main builtin_metadata_main
#include "metadata-oracle.cpp"
#undef main
#include <iomanip>
#include <cmath>
#include <cstring>
#include <functional>
#include <openvdb/tools/VelocityFields.h>
using namespace openvdb;
using namespace openvdb::math;
std::ofstream mapsOut;int mapCount=0;
void vec(std::ostream& out,const Vec3d& value){out<<'['<<value[0]<<','<<value[1]<<','<<value[2]<<']';}
void mat(std::ostream& out,const Mat4d& value){out<<'[';for(int i=0;i<16;++i){if(i)out<<',';out<<value.asPointer()[i];}out<<']';}
void mat(std::ostream& out,const Mat3d& value){out<<'[';for(int i=0;i<9;++i){if(i)out<<',';out<<value.asPointer()[i];}out<<']';}
Transform::Ptr exact(const MapBase::Ptr& map){std::stringstream bytes;writeString(bytes,map->type());map->write(bytes);io::setCurrentVersion(bytes);auto transform=Transform::Ptr(new Transform);transform->read(bytes);return transform;}
std::string wire(const MapBase::Ptr& map){std::ostringstream stream(std::ios::binary);writeString(stream,map->type());map->write(stream);return stream.str();}
std::vector<Vec3d> samplePoints(){return {Vec3d(0),Vec3d(1),Vec3d(-0.5,0.5,-1.5),Vec3d(1.25,-2.5,0.75),Vec3d(1.249999999625,-2.499999999625,1.124999999625),Vec3d(6291457.296875,-6291458.59375,0.890625),Vec3d(1e-9,-1e-9,-1e-7)};}
Mat3d hessian(){return Mat3d(1.25,-0.75,0.625,0.125,2.5,-1.25,-0.5,0.375,3.75);}
std::vector<MapBase::Ptr> bases(){std::vector<MapBase::Ptr> values;auto add=[&](MapBase* p){values.emplace_back(p);};
 add(new ScaleMap);add(new ScaleMap(Vec3d(.375)));add(new ScaleMap(Vec3d(-.7,1.125,1.375)));add(new UniformScaleMap);add(new UniformScaleMap(.375));add(new TranslationMap);add(new TranslationMap(Vec3d(1.25,-2.5,.75)));add(new ScaleTranslateMap(Vec3d(.375),Vec3d(1.25,-2.5,.75)));add(new UniformScaleTranslateMap(.375,Vec3d(1.25,-2.5,.75)));add(new ScaleTranslateMap(Vec3d(-.7,1.125,1.375),Vec3d(-.25,.75,1.125)));add(new UnitaryMap);add(new UnitaryMap(Z_AXIS,.21));add(new UnitaryMap(Mat3d(-1,0,0,0,1,0,0,0,1)));add(new AffineMap);
 Mat4d matrix=Mat4d::identity();matrix.preScale(Vec3d(.375));matrix.postTranslate(Vec3d(1.25,-2.5,.75));add(new AffineMap(matrix));matrix=Mat4d::identity();matrix.preScale(Vec3d(.7,1.125,1.375));matrix.postRotate(Z_AXIS,.21);matrix.postShear(X_AXIS,Y_AXIS,.13);matrix.postTranslate(Vec3d(-.25,.75,1.125));add(new AffineMap(matrix));
 add(new NonlinearFrustumMap(BBoxd(Vec3d(-8,-6,-4),Vec3d(8,6,12)),.65,9.0,AffineMap(Mat4d::identity()).preScale(Vec3d(.75))));add(new ScaleMap(Vec3d(1e-4,1,1)));matrix=Mat4d::identity();matrix.preScale(Vec3d(1e-9,1,1));add(new AffineMap(matrix));add(new TranslationMap(Vec3d(1e17,-1e17,3e16)));matrix=Mat4d::identity();matrix.preScale(Vec3d(.375));matrix.postTranslate(Vec3d(1e17,-1e17,3e16));add(new AffineMap(matrix));
 auto cached=MapBase::Ptr(new ScaleMap(Vec3d(.375)));std::string raw=wire(cached);size_t prefix=4+cached->type().size();double inv=std::nextafter(1/.375,4.0);std::memcpy(raw.data()+prefix+48,&inv,8);std::stringstream input(raw);io::setCurrentVersion(input);auto t=Transform::Ptr(new Transform);t->read(input);values.push_back(t->baseMap()->copy());return values;}
void emitMap(int source,const char* operation,const MapBase::Ptr& map){if(mapCount++)mapsOut<<",\n";auto affine=map->getAffineMap();mapsOut<<"{\"source\":"<<source<<",\"operation\":\""<<operation<<"\",\"type\":\""<<map->type()<<"\",\"wire\":\""<<hex(wire(map))<<"\",\"uniform\":"<<(map->hasUniformScale()?"true":"false")<<",\"identity\":"<<(exact(map)->isIdentity()?"true":"false")<<",\"determinant\":"<<map->determinant()<<",\"voxelSize\":";vec(mapsOut,map->voxelSize());mapsOut<<",\"matrix\":";mat(mapsOut,affine->getMat4());mapsOut<<",\"inverseMatrix\":";mat(mapsOut,affine->getMat4().inverse());mapsOut<<",\"ijc\":";mat(mapsOut,map->applyIJC(hessian()));mapsOut<<",\"samples\":[";bool first=true;for(const auto& point:samplePoints()){if(!first)mapsOut<<',';first=false;mapsOut<<"{\"point\":";vec(mapsOut,point);mapsOut<<",\"mapped\":";vec(mapsOut,map->applyMap(point));mapsOut<<",\"inverse\":";vec(mapsOut,map->applyInverseMap(point));mapsOut<<",\"jacobian\":";vec(mapsOut,map->applyJacobian(point));mapsOut<<",\"inverseJacobian\":";vec(mapsOut,map->applyInverseJacobian(point));mapsOut<<",\"jt\":";vec(mapsOut,map->applyJT(point));mapsOut<<",\"ijt\":";vec(mapsOut,map->applyIJT(point));mapsOut<<'}';}mapsOut<<"]}";}
void attempt(int source,const std::string& operation,const std::function<MapBase::Ptr()>& create){MapBase::Ptr map;try{map=create();}catch(const openvdb::Exception&){if(mapCount++)mapsOut<<",\n";mapsOut<<"{\"source\":"<<source<<",\"operation\":\""<<operation<<"\",\"error\":true}";return;}emitMap(source,operation.c_str(),map);}
Vec3d boundaryIndex(int i){switch(i){case 0:return Vec3d(0);case 1:return Vec3d(-.5,.5,-1.5);case 2:return Vec3d(-5);case 3:return Vec3d(5);case 4:return Vec3d(-5.5,5.5,-5.5);case 5:return Vec3d(7.75,-8.125,6.625);case 6:return Vec3d(-1e-9,1e-9,.999999999);default:return Vec3d(16777216.125,-16777216.25,.375);}}
template<class Grid,bool Staggered,int Order>void boundaryCase(std::ostream& out,bool& first){using T=typename Grid::ValueType::ValueType;using V=typename Grid::ValueType;auto grid=Grid::create(V(T(-.125),T(.25),T(.375)));auto transform=Transform::createLinearTransform(.375);transform->postTranslate(Vec3d(1.25,-2.5,.75));grid->setTransform(transform);for(int x=-5;x<=5;++x)for(int y=-5;y<=5;++y)for(int z=-5;z<=5;++z){V value(T(.03125*x*x+.0625*y-.0234375*z+.2),T(-.015625*y*y+.125*z+.015625*x*z-.1),T(.046875*z*z-.0625*x+.03125*x*y+.3));Coord coord(x,y,z);grid->tree().setValue(coord,value);if((x+y+z)%5==0)grid->tree().setValueOff(coord);}tools::VelocitySampler<Grid,Staggered,Order> sampler(*grid);if(!first)out<<',';first=false;out<<"{\"precision\":\""<<(std::is_same<T,float>::value?"float":"double")<<"\",\"order\":"<<Order<<",\"staggered\":"<<(Staggered?"true":"false")<<",\"samples\":[";for(int i=0;i<8;++i){if(i)out<<',';Vec3d world=grid->indexToWorld(boundaryIndex(i));Vec3s worldFloat(world);V value,valueFloat;bool active=sampler.sample(world,value),activeFloat=sampler.sample(worldFloat,valueFloat);out<<"{\"world\":";vec(out,world);out<<",\"sample\":";vec(out,Vec3d(value));out<<",\"sampleFloat\":";vec(out,Vec3d(valueFloat));out<<",\"active\":"<<(active?"true":"false")<<",\"activeFloat\":"<<(activeFloat?"true":"false")<<'}';}out<<"]}";}
template<class Grid>void boundaryCases(std::ostream& out,bool& first){boundaryCase<Grid,false,0>(out,first);boundaryCase<Grid,false,1>(out,first);boundaryCase<Grid,false,2>(out,first);boundaryCase<Grid,true,0>(out,first);boundaryCase<Grid,true,1>(out,first);boundaryCase<Grid,true,2>(out,first);}
void generateBoundaries(const fs::path& directory){std::ofstream out(directory/"native-map-velocity.json.tmp");out<<std::setprecision(17)<<"{\"upstreamCommit\":\"f42248c35a9f7bb30641a8a74d9075ce7d1ddcaf\",\"nativeMap\":\"UniformScaleTranslateMap\",\"cases\":[";bool first=true;boundaryCases<Vec3SGrid>(out,first);boundaryCases<Vec3DGrid>(out,first);out<<"]}\n";out.close();fs::path target=directory/"native-map-velocity.json";if(fs::exists(target))fs::remove(target);fs::rename(directory/"native-map-velocity.json.tmp",target);}
void generateMaps(const fs::path& directory){fs::create_directories(directory);mapsOut.open(directory/"native-maps.json.tmp");mapsOut<<std::setprecision(17)<<"[\n";auto values=bases();
 for(size_t i=0;i<values.size();++i){auto map=values[i];auto run=[&](const std::string& name,const std::function<MapBase::Ptr()>& create){attempt(int(i),name,create);};
 run("base",[&](){return map;});run("map-copy",[&](){return map->copy();});run("transform",[&](){return Transform(map).baseMap()->copy();});run("transform-copy",[&](){return exact(map)->copy()->baseMap()->copy();});if(map->isLinear())run("inverse",[&](){return map->inverseMap();});
 for(int mode=0;mode<2;++mode){bool pre=mode==0;run(pre?"pre-translate":"post-translate",[&](){return pre?map->preTranslate(Vec3d(.125,-.75,2.25)):map->postTranslate(Vec3d(.125,-.75,2.25));});run(pre?"pre-uniform":"post-uniform",[&](){return pre?map->preScale(Vec3d(2)):map->postScale(Vec3d(2));});run(pre?"pre-scale":"post-scale",[&](){return pre?map->preScale(Vec3d(.75,1.5,-.5)):map->postScale(Vec3d(.75,1.5,-.5));});for(int axis=0;axis<3;++axis){run((pre?"pre-rotate-":"post-rotate-")+std::to_string(axis),[&](){return pre?map->preRotate(.21,Axis(axis)):map->postRotate(.21,Axis(axis));});run((pre?"pre-shear-":"post-shear-")+std::to_string(axis),[&](){return pre?map->preShear(.13,Axis(axis),Axis((axis+1)%3)):map->postShear(.13,Axis(axis),Axis((axis+1)%3));});}}
 Mat4d m=Mat4d::identity();m.preScale(Vec3d(.875,1.25,1.5));m.postTranslate(Vec3d(.25,-.5,1));run("pre-mult",[&](){auto t=exact(map);t->preMult(m);return t->baseMap()->copy();});run("post-mult",[&](){auto t=exact(map);t->postMult(m);return t->baseMap()->copy();});
 }
 emitMap(-1,"default",Transform().baseMap()->copy());emitMap(-1,"factory-scale",Transform::createLinearTransform(.375)->baseMap()->copy());Mat4d m=Mat4d::identity();m.preScale(Vec3d(.375));m.postTranslate(Vec3d(1.25,-2.5,.75));emitMap(-1,"factory-matrix",Transform::createLinearTransform(m)->baseMap()->copy());
 mapsOut<<"\n]\n";mapsOut.close();fs::path target=directory/"native-maps.json";if(fs::exists(target))fs::remove(target);fs::rename(directory/"native-maps.json.tmp",target);
 GridPtrVec grids;for(size_t i=0;i<values.size();++i){if(i==19||i==20)continue;auto grid=FloatGrid::create();grid->setName("map_"+std::to_string(i));grid->setTransform(exact(values[i]));grid->tree().setValueOn(Coord(-1,2,3),float(i)+.25f);grids.push_back(grid);}for(int compression:{0,4,6}){io::File file((directory/("native-maps-"+std::to_string(compression)+".vdb")).string());file.setCompression(compression);file.setGridStatsMetadataEnabled(false);file.write(grids);}generateBoundaries(directory);std::cout<<"Generated "<<mapCount<<" native map cases from "<<values.size()<<" source maps\n";
}
void verifyMaps(const fs::path& actual,const fs::path& expected){std::ifstream a(actual,std::ios::binary),e(expected,std::ios::binary);io::Stream af(a,false),ef(e,false);auto ag=af.getGrids(),eg=ef.getGrids();if(ag->size()!=eg->size())throw std::runtime_error("grid count");for(size_t i=0;i<ag->size();++i){const auto& at=(*ag)[i]->transform();const auto& et=(*eg)[i]->transform();if(at.mapType()!=et.mapType()||wire(at.baseMap()->copy())!=wire(et.baseMap()->copy()))throw std::runtime_error("map wire mismatch "+std::to_string(i));for(const auto& p:samplePoints())if(at.indexToWorld(p)!=et.indexToWorld(p)||at.worldToIndex(p)!=et.worldToIndex(p))throw std::runtime_error("map arithmetic mismatch");auto av=gridPtrCast<FloatGrid>((*ag)[i]),ev=gridPtrCast<FloatGrid>((*eg)[i]);if(av->tree().getValue(Coord(-1,2,3))!=ev->tree().getValue(Coord(-1,2,3)))throw std::runtime_error("voxel mismatch");}std::cout<<"Native map wire/arithmetic verified for "<<ag->size()<<" grids\n";}
int main(int argc,char** argv){try{initialize();if(argc==3&&std::string(argv[1])=="generate")generateMaps(argv[2]);else if(argc==4&&std::string(argv[1])=="verify")verifyMaps(argv[2],argv[3]);else throw std::runtime_error("usage: maps-reference generate directory | verify actual expected");return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
